package com.cpf.batch.runtime; import java.util.regex.Pattern;
public final class SensitiveTextSanitizer { private static final Pattern KV=Pattern.compile("(?i)(password|passwd|pwd|secret|token|authorization|api[-_]?key|client[-_]?secret)\\s*[:=]\\s*([^\\s,;]+)"); private static final Pattern BEARER=Pattern.compile("(?i)Bearer\\s+[A-Za-z0-9._~+/=-]+"); private SensitiveTextSanitizer(){} public static String sanitize(String v){ if(v==null)return null; String s=KV.matcher(v).replaceAll("$1=***"); s=BEARER.matcher(s).replaceAll("Bearer ***"); return s.length()>4000?s.substring(0,4000)+"...[truncated]":s; } }
